  const ZOD_DE = ["du Rat", "du Buffle", "du Tigre", "du Lapin", "du Dragon", "du Serpent", "du Cheval", "de la Chèvre", "du Singe", "du Coq", "du Chien", "du Cochon"];
  // l'année lunaire commence fin janvier ou en février : la fête tombe toujours au début de l'année de l'animal
  const zodIndex = (y) => (((y - 4) % 12) + 12) % 12;
